797	    ///
798	    /// ```js
799	    /// // Function
800	    /// function foo() {
801	    ///    foo(); // Refers to the function itself, treated as a self-call
802	    /// }
803	    ///
804	    /// foo(); // This call expression is outside the function, not a self-call
805	    ///
806	    /// // Class
807	    /// class Foo {
808	    ///   constructor() { }
809	    ///   bar() {
810	    ///    new Foo(); // Refers to the class itself, treated as a self-call
811	    ///   }
