824	            let span = self.get_ref_span(reference);
825	            redeclarations.iter().any(|decl| {
826	                decl.flags.intersects(SymbolFlags::Function)
827	                    && self.nodes().kind(decl.declaration).span().contains_inclusive(span)
828	            })
