187	    /// Checks for references within for..in and for..of conditions (not
188	    /// bodies). These are always considered usages since their removal would
189	    /// introduce syntax and/or semantic errors.
190	    ///
191	    /// ## Examples
192	    /// ```ts
193	    /// // should return true
194	    /// var a;
195	    /// for (a in obj) {}
196	    /// for (a of iter) {}
197	    ///
198	    /// // should return false
199	    /// var b;
200	    /// for (let a in obj) { fn(b) }
201	    /// for (let a of iter) { fn(b) }
202	    /// ```
203	    fn is_used_in_for_of_loop(&self, reference: &Reference) -> bool {
204	        for parent in self.nodes().ancestors(reference.node_id()) {
205	            match parent.kind() {
206	                AstKind::ParenthesizedExpression(_)
207	                | AstKind::IdentifierReference(_)
208	                | AstKind::ComputedMemberExpression(_)
209	                | AstKind::StaticMemberExpression(_)
210	                | AstKind::PrivateFieldExpression(_)
211	                | AstKind::AssignmentTargetPropertyIdentifier(_)
212	                | AstKind::ArrayAssignmentTarget(_)
213	                | AstKind::ObjectAssignmentTarget(_) => {}
214	                AstKind::ForInStatement(ForInStatement { body, .. })
215	                | AstKind::ForOfStatement(ForOfStatement { body, .. }) => match body {
216	                    Statement::ReturnStatement(_) => return true,
217	                    Statement::BlockStatement(b) => {
218	                        return b
219	                            .body
220	                            .first()
221	                            .is_some_and(|s| matches!(s, Statement::ReturnStatement(_)));
222	                    }
223	                    _ => return false,
224	                },
225	                _ => return false,
226	            }
227	        }
228	
229	        false
230	    }
